-- Additive Modulox source authority for original native BOSS43 in final rooms.
-- The immutable room rows, roles, counts and routes are not mutated.
CREATE TABLE recurring_modulox_native_boss_authority (
 definition_id integer NOT NULL,version integer NOT NULL,boss_reference integer NOT NULL,
 native_property_id integer NOT NULL CHECK(native_property_id=43),
 source_authority text NOT NULL CHECK(length(source_authority)>0),
 proof_sha256 text NOT NULL CHECK(proof_sha256 ~ '^[0-9a-f]{64}$'),
 provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object'),
 PRIMARY KEY(definition_id,version,boss_reference),UNIQUE(definition_id,version),
 FOREIGN KEY(definition_id,version,boss_reference) REFERENCES recurring_modulox_authority
);
CREATE TABLE recurring_modulox_native_boss_occurrences (
 definition_id integer NOT NULL,version integer NOT NULL,monster_index integer NOT NULL CHECK(monster_index>=0),
 planned_role text NOT NULL CHECK(planned_role IN('monster','unknown')),
 count integer NOT NULL CHECK(count>0),
 PRIMARY KEY(definition_id,version,monster_index),
 FOREIGN KEY(definition_id,version) REFERENCES recurring_modulox_native_boss_authority(definition_id,version)
);
CREATE TRIGGER recurring_modulox_native_boss_authority_immutable BEFORE UPDATE OR DELETE ON recurring_modulox_native_boss_authority
 FOR EACH ROW EXECUTE FUNCTION recurring_hunter_immutable_source();
CREATE TRIGGER recurring_modulox_native_boss_occurrence_immutable BEFORE UPDATE OR DELETE ON recurring_modulox_native_boss_occurrences
 FOR EACH ROW EXECUTE FUNCTION recurring_hunter_immutable_source();

UPDATE recurring_hunter_daily_pools SET sealed=true WHERE pool_version=E'wakemu.daily-hunter50-modulox62-v1';
UPDATE recurring_hunter_daily_active SET pool_version=E'wakemu.daily-hunter50-modulox62-v1',enabled=false WHERE singleton;
